// Convertir a zona horaria de Madrid (Europe/Madrid)
const fechaMadrid = new Date(ahora.toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));

// Arrays en español
const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 
               'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

// Extraer componentes de la fecha en Madrid
const diaSemana = diasSemana[fechaMadrid.getDay()];
const dia = fechaMadrid.getDate();
const mes = meses[fechaMadrid.getMonth()];
const anio = fechaMadrid.getFullYear();
const hora = String(fechaMadrid.getHours()).padStart(2, '0');
const minutos = String(fechaMadrid.getMinutes()).padStart(2, '0');

// Construir la fecha en formato español completo
const fechaActual = diaSemana + ' ' + dia + ' de ' + mes + ' de ' + anio + ', ' + hora + ':' + minutos;

// Retornar el resultado
return {
  fechaActual: fechaActual
};

