/**
 * n8n Code node - Post-procesado de la salida del Basic LLM Chain
 * Conectar: "Basic LLM Chain" → este Code (main → main)
 */
const raw = items[0]?.json?.output;

// Validación básica
if (!raw || typeof raw !== 'object') {
	throw new Error('La salida no contiene el objeto "output" esperado.');
}

// Variables para cada posible respuesta
let respuesta_1 = '';
let respuesta_2 = '';
let respuesta_3 = '';

// Asignación condicional SIN limpiar saltos de línea
if (typeof raw.respuesta_1 === 'string' && raw.respuesta_1.trim() !== '') {
	respuesta_1 = raw.respuesta_1;
}

if (typeof raw.respuesta_2 === 'string' && raw.respuesta_2.trim() !== '') {
	respuesta_2 = raw.respuesta_2;
}

if (typeof raw.respuesta_3 === 'string' && raw.respuesta_3.trim() !== '') {
	respuesta_3 = raw.respuesta_3;
}

// Si no existe al menos una respuesta, dispara error para depurar
if (!respuesta_1 && !respuesta_2 && !respuesta_3) {
	throw new Error('No se encontró ninguna respuesta en la salida del LLM.');
}

// Construir objeto final
const formatted = {
	respuesta_1,
	respuesta_2,
	respuesta_3,
};

// Devolver un único ítem listo para los siguientes nodos
return [{ json: formatted }];
